-- 梦境护卫队 fh；只读 StarRocks 核查；执行于 2026-10-15（Asia/Shanghai）。
-- 每段是独立 SELECT，请逐段执行；date_time 左闭右开，观察截止 2026-10-15 00:00:00。
-- D7 = 建角时刻后 [0,168) 小时；D14 = [0,336) 小时；D25 = [0,600) 小时。不是日历日。
-- 9/30 建角 778 角完整随访 D7 与 D14；10/1–4 建角 3,825 角仅补充 D7。
-- 9/15–18 建角 4,950 角完整随访 D25。当前 SVN 配置与日志 version 不是同一种版本号。

-- 1. 各建角日的分母与时间边界
SELECT DATE(reg_ts) AS reg_date,COUNT(*) AS roles_n,MIN(reg_ts) AS min_reg_ts,MAX(reg_ts) AS max_reg_ts FROM (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time >= '2026-09-30 00:00:00' AND date_time < '2026-10-05 00:00:00' GROUP BY chr_id) c GROUP BY DATE(reg_ts) ORDER BY reg_date;

-- 2. 验证成长操作 ext 覆盖，窗口为 10 月 12 日至 14 日
SELECT type_name,COUNT(*) AS rows_n,COUNT(DISTINCT chr_id) AS roles_n,SUM(CASE WHEN ext IS NOT NULL AND ext<>'' THEN 1 ELSE 0 END) AS ext_n FROM dwd_virtual_items_fh WHERE date_time >= '2026-10-12 00:00:00' AND date_time < '2026-10-15 00:00:00' AND type_name IN ('主角装备升级','主角装备洗练','符文重铸','选择符文心愿保底池','基因解锁','秘宝洗炼消耗','秘宝技能升级消耗','载具等级升级','载具零件升级','载具零件激活','藏品升星','藏品激活') GROUP BY type_name ORDER BY rows_n DESC;

-- 3. 装备强化 10：任一部位与六部位
WITH c AS (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time >= '2026-09-30 00:00:00' AND date_time < '2026-10-05 00:00:00' GROUP BY chr_id), part_cross AS (SELECT v.chr_id,v.item_id,MIN(v.date_time) AS first_ts FROM dwd_virtual_items_fh v JOIN c ON c.chr_id=v.chr_id WHERE v.date_time >= '2026-09-30 00:00:00' AND v.date_time < '2026-10-15 00:00:00' AND v.type_name='主角装备升级' AND v.item_id BETWEEN 50003 AND 50008 AND get_json_int(v.ext,'$.升级前')<10 AND get_json_int(v.ext,'$.升级后')>=10 GROUP BY v.chr_id,v.item_id), milestones AS (SELECT chr_id,MIN(first_ts) AS first_ts,'任一装备部位强化10' AS milestone FROM part_cross GROUP BY chr_id UNION ALL SELECT chr_id,MAX(first_ts) AS first_ts,'六部位全强化10' AS milestone FROM part_cross GROUP BY chr_id HAVING COUNT(DISTINCT item_id)=6) SELECT m.milestone,COUNT(*) AS reached_by_14oct,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND m.first_ts>=c.reg_ts AND m.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS sep30_d7_168h,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND m.first_ts>=c.reg_ts AND m.first_ts<DATE_ADD(c.reg_ts, INTERVAL 336 HOUR) THEN 1 ELSE 0 END) AS sep30_d14_336h,SUM(CASE WHEN c.reg_ts>='2026-10-01 00:00:00' AND c.reg_ts<'2026-10-05 00:00:00' AND m.first_ts>=c.reg_ts AND m.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS oct1_4_d7_168h FROM milestones m JOIN c ON c.chr_id=m.chr_id GROUP BY m.milestone ORDER BY m.milestone;

-- 4. 装备强化 50：任一部位与六部位
WITH c AS (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time >= '2026-09-30 00:00:00' AND date_time < '2026-10-05 00:00:00' GROUP BY chr_id), part_cross AS (SELECT v.chr_id,v.item_id,MIN(v.date_time) AS first_ts FROM dwd_virtual_items_fh v JOIN c ON c.chr_id=v.chr_id WHERE v.date_time >= '2026-09-30 00:00:00' AND v.date_time < '2026-10-15 00:00:00' AND v.type_name='主角装备升级' AND v.item_id BETWEEN 50003 AND 50008 AND get_json_int(v.ext,'$.升级前')<50 AND get_json_int(v.ext,'$.升级后')>=50 GROUP BY v.chr_id,v.item_id), milestones AS (SELECT chr_id,MIN(first_ts) AS first_ts,'任一装备部位强化50' AS milestone FROM part_cross GROUP BY chr_id UNION ALL SELECT chr_id,MAX(first_ts) AS first_ts,'六部位全强化50' AS milestone FROM part_cross GROUP BY chr_id HAVING COUNT(DISTINCT item_id)=6) SELECT m.milestone,COUNT(*) AS reached_by_14oct,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND m.first_ts>=c.reg_ts AND m.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS sep30_d7_168h,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND m.first_ts>=c.reg_ts AND m.first_ts<DATE_ADD(c.reg_ts, INTERVAL 336 HOUR) THEN 1 ELSE 0 END) AS sep30_d14_336h,SUM(CASE WHEN c.reg_ts>='2026-10-01 00:00:00' AND c.reg_ts<'2026-10-05 00:00:00' AND m.first_ts>=c.reg_ts AND m.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS oct1_4_d7_168h FROM milestones m JOIN c ON c.chr_id=m.chr_id GROUP BY m.milestone ORDER BY m.milestone;

-- 5. 研究节点 10／30／100／10020／10060
WITH c AS (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time >= '2026-09-30 00:00:00' AND date_time < '2026-10-05 00:00:00' GROUP BY chr_id), reached AS (SELECT v.chr_id,get_json_int(v.ext,'$.激活节点') AS node_id,MIN(v.date_time) AS first_ts FROM dwd_virtual_items_fh v JOIN c ON c.chr_id=v.chr_id WHERE v.date_time >= '2026-09-30 00:00:00' AND v.date_time < '2026-10-15 00:00:00' AND v.type_name='基因解锁' AND v.item_id=2 AND get_json_int(v.ext,'$.激活节点') IN (10,30,100,10020,10060) GROUP BY v.chr_id,get_json_int(v.ext,'$.激活节点')) SELECT r.node_id,COUNT(*) AS reached_by_14oct,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS sep30_d7_168h,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 336 HOUR) THEN 1 ELSE 0 END) AS sep30_d14_336h,SUM(CASE WHEN c.reg_ts>='2026-10-01 00:00:00' AND c.reg_ts<'2026-10-05 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS oct1_4_d7_168h FROM reached r JOIN c ON c.chr_id=r.chr_id GROUP BY r.node_id ORDER BY r.node_id;

-- 6. 秘宝等级 2／3／4／5 直接跨级事件
WITH c AS (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time >= '2026-09-30 00:00:00' AND date_time < '2026-10-05 00:00:00' GROUP BY chr_id), thresholds AS (SELECT 2 AS target_level UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5), reached AS (SELECT v.chr_id,t.target_level,MIN(v.date_time) AS first_ts FROM dwd_virtual_items_fh v JOIN c ON c.chr_id=v.chr_id JOIN thresholds t ON get_json_int(v.ext,'$.洗炼前.等级')<t.target_level AND get_json_int(v.ext,'$.洗炼后.等级')>=t.target_level WHERE v.date_time >= '2026-09-30 00:00:00' AND v.date_time < '2026-10-15 00:00:00' AND v.item_id=5523001 AND v.type_name='秘宝洗炼消耗' GROUP BY v.chr_id,t.target_level) SELECT r.target_level,COUNT(*) AS reached_by_14oct,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS sep30_d7_168h,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 336 HOUR) THEN 1 ELSE 0 END) AS sep30_d14_336h,SUM(CASE WHEN c.reg_ts>='2026-10-01 00:00:00' AND c.reg_ts<'2026-10-05 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS oct1_4_d7_168h FROM reached r JOIN c ON c.chr_id=r.chr_id GROUP BY r.target_level ORDER BY r.target_level;

-- 7. 符文首次穿戴品质 5／6／7，限 55 前缀正式符文
WITH c AS (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time >= '2026-09-30 00:00:00' AND date_time < '2026-10-05 00:00:00' GROUP BY chr_id), rune_actions AS (SELECT p.chr_id,p.date_time,get_json_int(p.new_pet,'$.符文id') AS rune_id FROM dwd_pet_fh p JOIN c ON c.chr_id=p.chr_id WHERE p.date_time >= '2026-09-30 00:00:00' AND p.date_time < '2026-10-15 00:00:00' AND p.event IN ('符文穿戴','符文替换')), classified AS (SELECT chr_id,date_time,rune_id,CASE WHEN rune_id BETWEEN 5500000 AND 5599999 THEN MOD(rune_id,10) WHEN rune_id BETWEEN 55000000 AND 55999999 THEN MOD(FLOOR(rune_id/10),10) ELSE NULL END AS quality FROM rune_actions), thresholds AS (SELECT 5 AS quality UNION ALL SELECT 6 UNION ALL SELECT 7), reached AS (SELECT a.chr_id,t.quality,MIN(a.date_time) AS first_ts FROM classified a JOIN thresholds t ON a.quality>=t.quality GROUP BY a.chr_id,t.quality) SELECT r.quality,COUNT(*) AS reached_by_14oct,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS sep30_d7_168h,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 336 HOUR) THEN 1 ELSE 0 END) AS sep30_d14_336h,SUM(CASE WHEN c.reg_ts>='2026-10-01 00:00:00' AND c.reg_ts<'2026-10-05 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS oct1_4_d7_168h FROM reached r JOIN c ON c.chr_id=r.chr_id GROUP BY r.quality ORDER BY r.quality;

-- 8. 近期队列的载具等级 10／50
WITH c AS (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time >= '2026-09-30 00:00:00' AND date_time < '2026-10-05 00:00:00' GROUP BY chr_id), thresholds AS (SELECT 10 AS target_level UNION ALL SELECT 50), reached AS (SELECT v.chr_id,t.target_level,MIN(v.date_time) AS first_ts FROM dwd_virtual_items_fh v JOIN c ON c.chr_id=v.chr_id JOIN thresholds t ON get_json_int(v.ext,'$.升级前等级')<t.target_level AND get_json_int(v.ext,'$.目标等级')>=t.target_level WHERE v.date_time >= '2026-09-30 00:00:00' AND v.date_time < '2026-10-15 00:00:00' AND v.item_id=63 AND v.type_name='载具等级升级' GROUP BY v.chr_id,t.target_level) SELECT r.target_level,COUNT(*) AS reached_by_14oct,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS sep30_d7_168h,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 336 HOUR) THEN 1 ELSE 0 END) AS sep30_d14_336h,SUM(CASE WHEN c.reg_ts>='2026-10-01 00:00:00' AND c.reg_ts<'2026-10-05 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS oct1_4_d7_168h FROM reached r JOIN c ON c.chr_id=r.chr_id GROUP BY r.target_level ORDER BY r.target_level;

-- 9. 近期队列的任一藏品 2／3／5／10 星
WITH c AS (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time >= '2026-09-30 00:00:00' AND date_time < '2026-10-05 00:00:00' GROUP BY chr_id), thresholds AS (SELECT 2 AS target_star UNION ALL SELECT 3 UNION ALL SELECT 5 UNION ALL SELECT 10), reached AS (SELECT v.chr_id,t.target_star,MIN(v.date_time) AS first_ts FROM dwd_virtual_items_fh v JOIN c ON c.chr_id=v.chr_id JOIN thresholds t ON get_json_int(v.ext,'$.升星前')<t.target_star AND get_json_int(v.ext,'$.目标星级')>=t.target_star WHERE v.date_time >= '2026-09-30 00:00:00' AND v.date_time < '2026-10-15 00:00:00' AND v.type_name='藏品升星' AND v.item_id BETWEEN 6210000 AND 6219999 GROUP BY v.chr_id,t.target_star) SELECT r.target_star,COUNT(*) AS reached_by_14oct,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS sep30_d7_168h,SUM(CASE WHEN c.reg_ts>='2026-09-30 00:00:00' AND c.reg_ts<'2026-10-01 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 336 HOUR) THEN 1 ELSE 0 END) AS sep30_d14_336h,SUM(CASE WHEN c.reg_ts>='2026-10-01 00:00:00' AND c.reg_ts<'2026-10-05 00:00:00' AND r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts, INTERVAL 168 HOUR) THEN 1 ELSE 0 END) AS oct1_4_d7_168h FROM reached r JOIN c ON c.chr_id=r.chr_id GROUP BY r.target_star ORDER BY r.target_star;

-- 10. 较早注册队列的载具等级 10／50：D25 精确 600 小时
WITH c AS (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time>='2026-09-15 00:00:00' AND date_time<'2026-09-19 00:00:00' GROUP BY chr_id), thresholds AS (SELECT 10 AS target_level UNION ALL SELECT 50), reached AS (SELECT v.chr_id,t.target_level,MIN(v.date_time) AS first_ts FROM dwd_virtual_items_fh v JOIN c ON c.chr_id=v.chr_id JOIN thresholds t ON get_json_int(v.ext,'$.升级前等级')<t.target_level AND get_json_int(v.ext,'$.目标等级')>=t.target_level WHERE v.date_time>='2026-09-15 00:00:00' AND v.date_time<'2026-10-15 00:00:00' AND v.item_id=63 AND v.type_name='载具等级升级' GROUP BY v.chr_id,t.target_level) SELECT r.target_level,COUNT(*) AS reached_by_14oct,SUM(CASE WHEN r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts,INTERVAL 600 HOUR) THEN 1 ELSE 0 END) AS d25_600h_roles FROM reached r JOIN c ON c.chr_id=r.chr_id GROUP BY r.target_level ORDER BY r.target_level;

-- 11. 较早注册队列的任一藏品 2／5／10 星：D25 精确 600 小时
WITH c AS (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time>='2026-09-15 00:00:00' AND date_time<'2026-09-19 00:00:00' GROUP BY chr_id), thresholds AS (SELECT 2 AS target_star UNION ALL SELECT 5 UNION ALL SELECT 10), reached AS (SELECT v.chr_id,t.target_star,MIN(v.date_time) AS first_ts FROM dwd_virtual_items_fh v JOIN c ON c.chr_id=v.chr_id JOIN thresholds t ON get_json_int(v.ext,'$.升星前')<t.target_star AND get_json_int(v.ext,'$.目标星级')>=t.target_star WHERE v.date_time>='2026-09-15 00:00:00' AND v.date_time<'2026-10-15 00:00:00' AND v.type_name='藏品升星' AND v.item_id BETWEEN 6210000 AND 6219999 GROUP BY v.chr_id,t.target_star) SELECT r.target_star,COUNT(*) AS reached_by_14oct,SUM(CASE WHEN r.first_ts>=c.reg_ts AND r.first_ts<DATE_ADD(c.reg_ts,INTERVAL 600 HOUR) THEN 1 ELSE 0 END) AS d25_600h_roles FROM reached r JOIN c ON c.chr_id=r.chr_id GROUP BY r.target_star ORDER BY r.target_star;

-- 12. 六种可判定首次状态的操作：检查必需 JSON 字段是否完整
SELECT type_name,COUNT(*) AS rows_n,SUM(CASE WHEN type_name='主角装备升级' AND (get_json_int(ext,'$.升级前') IS NULL OR get_json_int(ext,'$.升级后') IS NULL OR get_json_int(ext,'$.部位') IS NULL) THEN 1 WHEN type_name='基因解锁' AND get_json_int(ext,'$.激活节点') IS NULL THEN 1 WHEN type_name='秘宝洗炼消耗' AND (get_json_int(ext,'$.洗炼前.等级') IS NULL OR get_json_int(ext,'$.洗炼后.等级') IS NULL) THEN 1 WHEN type_name='载具等级升级' AND (get_json_int(ext,'$.升级前等级') IS NULL OR get_json_int(ext,'$.目标等级') IS NULL) THEN 1 WHEN type_name='载具零件升级' AND (get_json_int(ext,'$.升级前等级') IS NULL OR get_json_int(ext,'$.目标等级') IS NULL OR get_json_int(ext,'$.零件id') IS NULL) THEN 1 WHEN type_name='藏品升星' AND (get_json_int(ext,'$.升星前') IS NULL OR get_json_int(ext,'$.目标星级') IS NULL OR get_json_int(ext,'$.藏品id') IS NULL) THEN 1 ELSE 0 END) AS missing_required_json_n FROM dwd_virtual_items_fh WHERE date_time >= '2026-10-12 00:00:00' AND date_time < '2026-10-15 00:00:00' AND type_name IN ('主角装备升级','基因解锁','秘宝洗炼消耗','载具等级升级','载具零件升级','藏品升星') GROUP BY type_name ORDER BY rows_n DESC;

-- 13. 较早注册队列的分母；检查 D25 随访资格
SELECT COUNT(*) AS roles_n,MIN(reg_ts) AS min_reg_ts,MAX(reg_ts) AS max_reg_ts FROM (SELECT chr_id,MIN(the_date_time) AS reg_ts FROM dwd_chr_v9_fh WHERE date_time >= '2026-09-15 00:00:00' AND date_time < '2026-09-19 00:00:00' GROUP BY chr_id) c;
